(function(){
  if(typeof gsap==="undefined")return;      // בלי GSAP המספרים האמיתיים כבר כתובים ב-HTML
  // מספר שמשתנה הוא שינוי טקסט ולא תנועה (motion.md §4), ולכן הוא סופר גם בהפחתת תנועה
