.ff-field input,.ff-field textarea{width:100%;font:inherit;font-size:16px;color:var(--ink, #16182b);background:var(--card, #fff);
  border:1px solid var(--line, #e4e4ee);border-radius:12px;padding:26px 16px 10px;transition:border-color .25s,box-shadow .25s}
