/* B35 · ציר תהליך אנכי עם קו שמתמלא */
/* כל הגאומטריה נגזרת משלושה משתנים. כשהקו והעיגולים מקבלים כל אחד clamp משלו
   הם מתיישרים במקרה ברוחב אחד ומתפצלים בכל השאר, וזה נראה כמו קו עקום. */
.vt{--vt-pad:clamp(46px,6vw,72px);--vt-x:clamp(4px,1vw,12px);--vt-dot:clamp(24px,3vw,34px);
  position:relative;max-width:min(780px,92vw);margin-inline:auto;padding-inline-start:var(--vt-pad)}
.vt-rail{position:absolute;inset-block:14px 10px;width:2px;background:var(--line, #e4e4ee);border-radius:2px;
  inset-inline-start:calc(var(--vt-x) + var(--vt-dot)/2 - 1px)}
/* מצב הבסיס הוא הציר השלם: קו מלא וכל השלבים דלוקים. כך הוא נראה בתנועה מופחתת וכשהספרייה חסומה.
   המצב הכבוי חי רק תחת .vt-live, שהסקריפט מוסיף כשהוא באמת מנפיש */
.vt-fill{position:absolute;inset-block-start:0;inset-inline:0;height:100%;background:var(--accent, #4a3aff);border-radius:2px}
.vt-step{position:relative;padding-block:clamp(18px,2.4vw,34px)}
.vt-dot{position:absolute;inset-inline-start:calc(var(--vt-pad) * -1 + var(--vt-x));top:calc(clamp(18px,2.4vw,34px) + 2px);
  width:var(--vt-dot);height:var(--vt-dot);border-radius:50%;background:var(--accent, #4a3aff);border:2px solid var(--accent, #4a3aff);
  display:grid;place-items:center;font-size:13px;font-weight:700;color:var(--accent-ink, #fff);transition:background .35s,border-color .35s,color .35s}
.vt-live .vt-step:not(.on) .vt-dot{background:var(--card, #fff);border-color:var(--line, #e4e4ee);color:var(--muted, #6a6d85)}
.vt-step h3{margin:0 0 6px;font-size:clamp(19px,2vw,26px);color:var(--ink, #16182b);transition:color .35s}
.vt-live .vt-step:not(.on) h3{color:var(--muted, #6a6d85)}
/* רגע ההדלקה של .vt-live: בלי transition, אחרת השלבים שעוד לא הגיע אליהם הקו נכבים בדהייה מול העיניים בטעינה */
.vt-init .vt-dot,.vt-init h3{transition:none}
.vt-step p{margin:0;color:var(--muted, #6a6d85);font-size:16px;line-height:1.65;max-width:56ch}
.vt-when{display:inline-block;margin-top:8px;font-size:12px;letter-spacing:0;color:var(--muted, #6a6d85);border:1px solid var(--line, #e4e4ee);border-radius:999px;padding:4px 11px}

