/* מחלקות עזר של המאגר שהרכיב הזה משתמש בהן */
.stage{padding:var(--sec, clamp(120px, 12vw, 260px)) var(--gutter, clamp(24px, 5vw, 96px));position:relative}
.stage.tight{padding-block:clamp(48px,5vw,90px)}
.stage.full{padding-inline:0}

/* B51 · באנר עוגיות עם הגדרות וזיכרון */
.ck{position:fixed;inset-inline:16px;bottom:16px;z-index:70;max-width:560px;margin-inline:auto;
  background:var(--card, #fff);border:1px solid var(--line, #e4e4ee);border-radius:18px;padding:20px 22px;
  box-shadow:0 18px 50px rgba(20,20,40,.16)}
.ck[hidden]{display:none}
.ck h4{margin:0 0 8px;font-size:17px}
.ck p{margin:0 0 16px;font-size:14.5px;line-height:1.65;color:var(--muted, #6a6d85)}
.ck p a{color:var(--accent, #4a3aff)}
.ck-row{display:flex;gap:8px;flex-wrap:wrap}
.ck-btn{font-family:inherit;font-size:14px;min-height:44px;padding:11px 18px;border-radius:999px;cursor:pointer;border:1px solid var(--line, #e4e4ee);
  background:var(--bg, #f7f7fa);color:var(--ink, #16182b)}
.ck-btn.main{background:var(--ink, #16182b);border-color:var(--ink, #16182b);color:var(--bg, #f7f7fa)}
.ck-btn.link{border-color:transparent;background:none;color:var(--muted, #6a6d85);text-decoration:underline;padding-inline:8px}
.ck-prefs{margin:4px 0 16px;display:grid;gap:2px}
/* display:grid גובר על התכונה hidden, ובלי השורה הזאת הפאנל פתוח כבר בהופעה הראשונה */
.ck-prefs[hidden]{display:none}
.ck-pref{display:flex;align-items:flex-start;gap:12px;padding:12px 0;border-top:1px solid var(--line, #e4e4ee)}
.ck-pref strong{display:block;font-size:14.5px;font-weight:600}
.ck-pref span{display:block;font-size:13px;color:var(--muted, #6a6d85);line-height:1.55;margin-top:2px}
.ck-sw{flex:none;width:44px;height:26px;border-radius:999px;background:#d5d5e0;border:0;cursor:pointer;padding:0;
  position:relative;transition:background .2s}
/* אזור לחיצה של 44 פיקסלים בלי לשנות את המראה (::after תפוס לידית) */
.ck-sw::before{content:"";position:absolute;inset:-9px -4px}
/* הידית מתחילה בצד ההתחלה. בעברית כבוי הוא ידית בימין ודלוק הוא ידית בשמאל, כמו בממשקי הטלפון בעברית */
.ck-sw::after{content:"";position:absolute;top:3px;inset-inline-start:3px;width:20px;height:20px;border-radius:50%;background:#fff /* qa-allow: white, ידית/סמן ולא משטח טקסט */;
  transition:transform .22s cubic-bezier(.2,.6,.2,1)}
.ck-sw[aria-checked="true"]{background:var(--accent, #4a3aff)}
.ck-sw[aria-checked="true"]::after{transform:translateX(18px)}
[dir="rtl"] .ck-sw[aria-checked="true"]::after{transform:translateX(-18px)}
.ck-sw[disabled]{opacity:.55;cursor:not-allowed}
/* הכפתור הצף בצד הסוף, כמו כל הכפתורים הצפים בתורה. בפרויקט עם כפתור נגישות או וואטסאפ מרימים את bottom מעליו */
.ck-reopen{position:fixed;inset-inline-end:16px;bottom:16px;z-index:69;font-family:inherit;font-size:13px;
  padding:9px 15px;border-radius:999px;border:1px solid var(--line, #e4e4ee);background:var(--card, #fff);color:var(--muted, #6a6d85);cursor:pointer}
.ck-reopen[hidden]{display:none}
.ck-state{max-width:min(620px,94vw);margin-inline:auto;text-align:center;color:var(--muted, #6a6d85);font-size:15px;line-height:1.8}
.ck-state code{background:var(--card, #fff);border:1px solid var(--line, #e4e4ee);border-radius:8px;padding:3px 8px;font-size:13px}
@media (prefers-reduced-motion: reduce){.ck-sw::after{transition:none}}

