/* מחלקות עזר של המאגר שהרכיב הזה משתמש בהן */
.ph{display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700;border-radius:var(--r, 14px)}
.ph-b{background:linear-gradient(160deg,#5f3dc4,#9775fa)}

/* B52 · הירו שמתקפל לתפריט דביק */
.fu-scope{--fu-h:100vh}
/* בלי GSAP ובהפחתת תנועה ההירו הוא בלוק רגיל בגובה מסך והתוכן מתחתיו.
   הדביקות והקיפול קיימים רק תחת .is-live, אחרת הירו דביק בגובה מסך מלא מכסה את כל העמוד */
.fu-mask{position:relative;z-index:60;height:var(--fu-h);overflow:hidden;background:var(--ink, #16182b);
  border-radius:0 0 var(--fu-r,0px) var(--fu-r,0px)}
.fu-scope.is-live .fu-mask{position:sticky;top:0}
.fu-media{position:absolute;inset:0;border-radius:0;font-size:0}
.fu-inner{position:absolute;inset:0;display:grid;grid-template-rows:auto 1fr;padding:18px clamp(16px,3vw,34px)}
.fu-nav{display:flex;align-items:center;justify-content:space-between;gap:16px;color:#fff;height:56px}
.fu-logo{font-weight:800;font-size:19px}
.fu-links{display:flex;gap:20px;font-size:14px;opacity:.9}
.fu-links a{color:#fff;text-decoration:none}
.fu-title{align-self:center;color:#fff;margin:0;font-size:clamp(32px,7vw,90px);line-height:1.05;max-width:14ch}
/* המרווח המשלים: מה שהמסכה מאבדת בגובה הוא מקבל, ולכן העמוד לא קופץ תוך כדי הקיפול */
.fu-gap{height:calc(100vh - var(--fu-h))}
/* הרצועה המקופלת נשארת דבוקה מעל התוכן. בלי ריפוד עליון בגובה שלה הכותרת הראשונה
   נכנסת מתחתיה והטקסט נראה כאילו הוא חופף להירו. --fu-bar נמדד מהתפריט עצמו ב-JS. */
.fu-body{padding:calc(var(--fu-bar,92px) + clamp(30px,6vw,80px)) var(--gutter, clamp(24px, 5vw, 96px)) 20vh;
  max-width:min(760px,92vw);margin-inline:auto}
.fu-body h3{font-size:clamp(22px,3vw,36px);margin:0 0 12px}
.fu-body p{color:var(--muted, #6a6d85);font-size:17px;line-height:1.8;margin:0 0 22px}
@media(max-width:700px){.fu-links{display:none}}

