.vs-bar{position:absolute;inset-inline:clamp(16px,6vw,80px);bottom:clamp(14px,2.5vh,26px);
  height:5px;border-radius:999px;overflow:hidden;background:rgba(255,255,255,.14)}
/* המילוי נחשף ב-clip-path ולא ב-width, כדי שכל עדכון גלילה לא יהיה layout. בעמוד עברי הוא מתמלא מימין */
