/* G57 · גלגל תמונות שמסתובב בגלילה */
/* בלי תנועה (וגם בלי JS) הפריטים הם גריד רגיל שכולו על המסך. הגלגל, הבמה הדביקה ו-300vh של גלילה קיימים רק תחת .is-live */
.wh{position:relative}
.wh-stick{padding-block:var(--sec, clamp(120px, 12vw, 260px))}
.wh-title{text-align:center;padding-inline:var(--gutter, clamp(24px, 5vw, 96px));margin-bottom:32px}
