/* G70 · כותרת שמתכווצת ומתעגנת לפינה */
.dk{position:relative}
.dk-stage{position:sticky;top:0;height:100vh;pointer-events:none;z-index:5}
/* העוגן הוא הפינה הימנית העליונה, ונקודת הקנה מידה שם, כך שההתכווצות מושכת אליה */
/* בלי GSAP או בהפחתת תנועה הכותרת כבר מעוגנת בפינה, במצב הסופי. רקע בצבע העמוד: התווית מסתירה
   את הטקסט שגולל מתחתיה במקום להידבק אליו, ולכן היא גם תופסת את הסמן (pointer-events:auto) */
.dk-title{position:absolute;top:26px;right:24px;margin:0;white-space:nowrap;
  font-size:clamp(30px,6vw,84px);font-weight:800;line-height:1;color:var(--ink, #16182b);
  background:var(--bg, #f7f7fa);padding:.1em .3em;border-radius:.3em;pointer-events:auto;
  transform-origin:100% 0%;transform:scale(.34);will-change:transform}
/* בטלפון התווית בחצי גודל: בשליש היא יצאה בגובה עשרה פיקסלים */
@media (max-width:767px){.dk-title{transform:scale(.5)}}
/* המרווח יושב על התוכן ולא על הפרק: ריפוד של האב אינו חלק מתיבת התוכן שלו,
   ו-sticky נעצר בגבול תיבת התוכן. מרווח על האב היה מקצר את אזור ההיצמדות. */
.dk-body{margin-top:-100vh;padding:100vh var(--gutter, clamp(24px, 5vw, 96px)) 60vh;max-width:min(760px,92vw);margin-inline:auto}
.dk-body p{font-size:17px;line-height:1.9;color:var(--muted, #6a6d85);margin:0 0 22px}
.dk-body h4{font-size:clamp(20px,2.4vw,30px);margin:40px 0 12px}

