if (typeof gsap !== "undefined") gsap.registerPlugin(ScrollTrigger);

(function(){
  if(typeof gsap==="undefined")return;   // בלי הספרייה הכותרת נשארת מעוגנת בפינה, כמו ב-CSS
  const title=document.querySelector(".dk-title");
  gsap.matchMedia().add({mob:"(max-width:767px)",desk:"(min-width:768px)",motion:"(prefers-reduced-motion: no-preference)"},ctx=>{
    if(!ctx.conditions.motion)return;   // בהפחתת תנועה: התווית המעוגנת מה-CSS, בלי מעבר
    // בלי שום מדידה: שני מצבים מוגדרים במלואם, ו-GSAP עושה אינטרפולציה בין אחוזים לפיקסלים.
    // מצב א: הקצה הימני במרכז המסך ואז דחיפה של חצי רוחב, כלומר מרכוז מדויק.
    // מצב ב: העוגן בפינה, ונקודת הקנה מידה שם, ולכן ההתכווצות מושכת אל הפינה.
    // הגודל הסופי זהה לזה שב-CSS: חצי בטלפון, שליש מעליו
    gsap.fromTo(title,
      {top:"50%",right:"50%",xPercent:50,yPercent:-50,scale:1},
      {top:"26px",right:"24px",xPercent:0,yPercent:0,scale:ctx.conditions.mob?.5:.34,ease:"none",
       scrollTrigger:{trigger:".dk",start:"top top",end:"+=70%",scrub:.5,invalidateOnRefresh:true}});
  });
})();

