@container (max-width:1023px){.q .stats{gap:24px}.q .stat b{font-size:51px}.q .ft .cols{grid-template-columns:1fr 1fr}}
@container (max-width:767px){.q .hd nav,.q .hd .acts .login{display:none}.q .hd .acts .btn{width:auto;min-height:44px}.q .lnk{padding-block:12px}.q .g3,.q .plans,.q .stats,.q .form .row{grid-template-columns:1fr}.q .stat b{font-size:44px}.q .proof{padding-top:calc(var(--sec, clamp(120px, 12vw, 260px)) + 56px)}.q .plan.rec{order:-1}.q .ft .cols{grid-template-columns:1fr;gap:28px}.q .state{padding-block:calc(var(--sec, clamp(120px, 12vw, 260px)) * 1.25)}}

