(function(){
  if(!matchMedia("(hover:hover) and (pointer:fine)").matches)return;
  const dock=document.querySelector(".dk"),icons=[...dock.querySelectorAll("a")],RANGE=140,MAX=1.7;
  function paint(x){
    // מרכז הפריסה של כל אייקון: המלבן על המסך פחות ההזזה הנוכחית (גם באמצע טרנזישן). ה-scale מהמרכז-תחתית לא מזיז אותו לרוחב
    const c=icons.map(a=>{const r=a.getBoundingClientRect();return r.left+r.width/2-new DOMMatrixReadOnly(getComputedStyle(a).transform).m41;});
    const s=c.map(v=>{const d=Math.abs(x-v);return d>RANGE?1:1+(MAX-1)*Math.cos((d/RANGE)*Math.PI/2);});   // קוסינוס: רך במרכז, מתאפס בקצה הטווח
    const W=icons[0].offsetWidth,ex=s.map(v=>(v-1)*W),G=ex.reduce((a,b)=>a+b,0);
    // דחיפת השכנים: כל אייקון זז בחצי מהגדילה שלו ועוד כל מה שגדל לפניו (לפי מיקום פיזי, משמאל לימין), והשורה נשארת ממורכזת
    const ord=c.map((v,i)=>i).sort((i,j)=>c[i]-c[j]);let acc=0;
    ord.forEach(i=>{icons[i].style.setProperty("--tx",(acc+ex[i]/2-G/2).toFixed(1)+"px");icons[i].style.setProperty("--s",s[i].toFixed(3));acc+=ex[i];});
    dock.style.setProperty("--g",(G/2).toFixed(1)+"px");
  }
  dock.addEventListener("mousemove",e=>paint(e.clientX));
  dock.addEventListener("mouseleave",()=>{icons.forEach(a=>{a.style.setProperty("--s",1);a.style.setProperty("--tx","0px");});dock.style.setProperty("--g","0px");});
})();

