(function(){
  const btn=document.querySelector(".hv-thumb"),modal=document.querySelector(".hv-modal"),frame=modal.querySelector(".hv-frame"),video=frame.querySelector("video"),close=modal.querySelector(".hv-close");
  const reduce=matchMedia("(prefers-reduced-motion: reduce)").matches,E="cubic-bezier(.2,.6,.2,1)",root=document.documentElement;
  // מחוץ לכל הקשר ערימה: הדר דביק לא יכסה את הסגירה, ו-transform על אב לא ישבור את position:fixed
  document.body.appendChild(modal);
  function open(){
    if(!video.src)video.src=video.dataset.src;
    const a=btn.getBoundingClientRect();modal.classList.add("on");
    const b=frame.getBoundingClientRect();
    if(!reduce){frame.animate([{transform:"translate("+(a.left-b.left)+"px,"+(a.top-b.top)+"px) scale("+(a.width/b.width)+","+(a.height/b.height)+")"},{transform:"none"}],{duration:520,easing:E});}
    requestAnimationFrame(()=>modal.classList.add("in"));
    // הלחיצה של הגולש מתירה קול; אם הדפדפן בכל זאת חוסם, מנגנים מושתק
    video.muted=false;video.play().catch(()=>{video.muted=true;video.play().catch(()=>{});});
    close.focus();
    root.style.overflow="hidden";root.style.scrollbarGutter="stable";   // הדף מתחת לא נגלל, והרוחב לא קופץ
    document.addEventListener("keydown",onKey);
  }
  function shut(){
    video.pause();modal.classList.remove("in");
    const a=btn.getBoundingClientRect(),b=frame.getBoundingClientRect();
    const anim=reduce?null:frame.animate([{transform:"none"},{transform:"translate("+(a.left-b.left)+"px,"+(a.top-b.top)+"px) scale("+(a.width/b.width)+","+(a.height/b.height)+")"}],{duration:420,easing:E});
    (anim?anim.finished:Promise.resolve()).then(()=>{modal.classList.remove("on");root.style.overflow="";root.style.scrollbarGutter="";btn.focus();});
    document.removeEventListener("keydown",onKey);
  }
  function onKey(e){
    if(e.key==="Escape"){shut();return;}
    // מלכודת פוקוס: aria-modal מחייב ש-Tab יישאר בתוך הדיאלוג
    if(e.key==="Tab"){const f=[video,close],i=f.indexOf(document.activeElement);e.preventDefault();f[(i+(e.shiftKey?-1:1)+f.length)%f.length].focus();}
  }
  btn.addEventListener("click",open);close.addEventListener("click",shut);
  modal.addEventListener("click",e=>{if(e.target===modal)shut();});
})();

