(function(){
  const root=document.querySelector(".dc"),wrap=root.parentElement,cards=[...root.querySelectorAll(".dc-card")],dots=document.querySelector(".dc-dots"),play=document.querySelector(".dc-play"),n=cards.length;
  const rq=matchMedia("(prefers-reduced-motion: reduce)"),mq=matchMedia("(max-width:767px)"),hasG=typeof gsap!=="undefined";
  let cur=0,timer=null,paused=rq.matches;   // בתנועה מופחתת מתחילים עצורים
  cards.forEach(()=>dots.appendChild(document.createElement("i")));
  function place(c,v,animate){
    if(!hasG){   // בלי GSAP (CDN חסום): אותו מיקום, בלי אנימציה, והקרוסלה עובדת
      c.style.transform="translate3d("+v.x+"px,0,"+v.z+"px) scale("+v.scale+")";c.style.opacity=v.opacity;c.style.zIndex=v.zIndex;return;}
    if(animate)gsap.to(c,Object.assign({duration:.7,ease:"power3.out",overwrite:true},v));
    else gsap.set(c,Object.assign({overwrite:true},v));
  }
  function layout(animate){
    const w=cards[0].offsetWidth,GAP=mq.matches?.28:.34;   // כמה מהרוחב זז כל כרטיס הצידה; קטן במובייל כדי שהשכנים יציצו
    cards.forEach((c,i)=>{
      let off=i-cur; if(off>n/2)off-=n; if(off<-n/2)off+=n;      // מסילה מעגלית: הקצר מבין שני הכיוונים
      const depth=Math.abs(off);
      // RTL: הבא נמצא משמאל, לכן ההיסט האופקי הפוך
      place(c,{x:-off*w*GAP,z:-depth*220,opacity:depth>2?0:1-depth*.28,scale:1-depth*.06,zIndex:n-depth},animate&&!rq.matches);
      c.setAttribute("aria-hidden",off!==0);
    });
    [...dots.children].forEach((d,i)=>d.classList.toggle("on",i===cur));
  }
  function go(step){cur=(cur+step+n)%n;layout(true);restart();}
  // רץ רק כשלא עצרו אותו ולא מרחפים מעליו
  function restart(){clearInterval(timer);timer=null;if(!paused&&!root.matches(":hover"))timer=setInterval(()=>go(1),3800);}
  function setPlay(){play.setAttribute("aria-pressed",String(!paused));play.setAttribute("aria-label",paused?"הפעלת ההתקדמות האוטומטית":"עצירת ההתקדמות האוטומטית");}
  play.addEventListener("click",()=>{paused=!paused;setPlay();restart();});
  // פוקוס מקלדת בתוך הקרוסלה עוצר אותה עד שהגולש מפעיל שוב בכפתור (כמו בדפוס הקרוסלה של WAI-ARIA)
  wrap.addEventListener("focusin",()=>{if(!paused&&wrap.querySelector(":focus-visible")){paused=true;setPlay();restart();}});
  setPlay();
  document.querySelector(".dc-next").addEventListener("click",()=>go(1));
  document.querySelector(".dc-prev").addEventListener("click",()=>go(-1));
  // מקלדת: בעברית חץ שמאלה = הבא
  root.addEventListener("keydown",e=>{if(e.key==="ArrowLeft")go(1);if(e.key==="ArrowRight")go(-1);});
  // גרירה עם סף, בלי ספרייה
  let x0=null;
  root.addEventListener("pointerdown",e=>{x0=e.clientX;root.classList.add("drag");root.setPointerCapture(e.pointerId);clearInterval(timer);});
  root.addEventListener("pointerup",e=>{if(x0===null)return;const dx=e.clientX-x0;x0=null;root.classList.remove("drag");if(Math.abs(dx)>40)go(dx<0?1:-1);else restart();});
  root.addEventListener("pointercancel",()=>{x0=null;root.classList.remove("drag");restart();});
  root.addEventListener("mouseenter",()=>clearInterval(timer));root.addEventListener("mouseleave",restart);
  layout(false);restart();
  addEventListener("resize",()=>layout(false));
})();

