.cq-mark::after{transform:rotate(90deg)}
/* רק עם עכבר אמיתי: במגע הבועה נשארה מורמת אחרי נגיעה. ובהפחתת תנועה בלי הרמה */
@media (hover:hover) and (pointer:fine) and (prefers-reduced-motion:no-preference){.cq-q:hover .cq-txt{transform:translateY(-2px)}}
.cq-q:focus-visible{outline:none}
.cq-q:focus-visible .cq-txt{outline:2px solid var(--accent, #4a3aff);outline-offset:3px}
.cq-item.open .cq-txt{background:var(--accent, #4a3aff);color:var(--accent-ink, #fff)}
.cq-item.open .cq-mark{background:var(--accent, #4a3aff);transform:rotate(45deg)}
.cq-item.open .cq-mark::before,.cq-item.open .cq-mark::after{background:var(--accent-ink, #fff)}
/* התשובה: גובה אמיתי ב-grid-template-rows, ובתוכו בועה שקופצת פנימה רק אחרי שהשורה נפתחה */
.cq-a{display:grid;grid-template-rows:0fr;width:100%;transition:grid-template-rows .42s cubic-bezier(.2,.6,.2,1)}
.cq-item.open .cq-a{grid-template-rows:1fr}
/* תשובה סגורה יוצאת גם מעץ הנגישות, אחרת קורא מסך מקריא את כולן. הסתרה אחרי 0.42 שנייה, כשהגובה כבר נסגר */
.cq-a>div{overflow:hidden;visibility:hidden;transition:visibility 0s linear .42s}
.cq-item.open .cq-a>div{visibility:visible;transition-delay:0s}
.cq-reply{display:flex;align-items:flex-end;gap:12px;justify-content:flex-end;padding:10px 4px 28px;
  opacity:0;transform:translateY(12px) scale(.97);transform-origin:left bottom;transition:opacity .25s,transform .25s cubic-bezier(.2,.6,.2,1)}
.cq-item.open .cq-reply{opacity:1;transform:none;transition:opacity .35s .12s,transform .45s .12s cubic-bezier(.2,.6,.2,1)}
.cq-bub{max-width:min(560px,100%);background:var(--card, #fff);color:var(--ink, #16182b);border:1px solid var(--line, #e4e4ee);padding:18px 24px;
  border-radius:26px 26px 26px 6px;font-size:16px;line-height:1.65;box-shadow:0 14px 34px -20px color-mix(in srgb,var(--ink, #16182b) 40%,transparent)}
.cq-bub p{margin:0}
.cq-av{flex:none;width:42px;height:42px;border-radius:50%;box-shadow:0 0 0 3px var(--card, #fff);font-size:15px}
@media (max-width:820px){.cq{grid-template-columns:1fr}.cq-side{position:static}}
@media (prefers-reduced-motion: reduce){.cq-a,.cq-a>div,.cq-item.open .cq-a>div,.cq-reply,.cq-item.open .cq-reply,.cq-txt,.cq-mark{transition-duration:.01ms;transition-delay:0s}}

