/* מחלקות עזר של המאגר שהרכיב הזה משתמש בהן */
.stage{padding:var(--sec, clamp(120px, 12vw, 260px)) var(--gutter, clamp(24px, 5vw, 96px));position:relative}
.stage.tight{padding-block:clamp(48px,5vw,90px)}
.stage.full{padding-inline:0}

/* B64 · תגיות שמצביעות על המסר המרכזי */
.aim{position:relative;height:min(78vh,640px);max-width:min(1240px,96vw);margin-inline:auto}
.aim-disc{position:absolute;left:50%;top:50%;width:min(56vh,460px,70vw);aspect-ratio:1;border-radius:50%;background:var(--ink, #16182b);color:var(--bg, #f7f7fa);
  display:grid;place-items:center;text-align:center;padding:9%;box-sizing:border-box;translate:-50% -50%;
  transform:scale(.55);opacity:0;transition:transform .9s cubic-bezier(.2,.6,.2,1),opacity .5s}
.aim-disc p{margin:0;font-size:clamp(22px,2.6vw,38px);line-height:1.2;font-weight:400;text-wrap:balance}
.aim-disc b{display:block;font-weight:800;color:color-mix(in srgb,var(--accent, #4a3aff) 55%,var(--bg, #f7f7fa))}
.aim-chip{position:absolute;left:var(--x);top:var(--y);translate:-50% -50%;transition:transform .8s cubic-bezier(.2,.6,.2,1),opacity .4s;
  transform:translate(var(--fx,0),var(--fy,0)) scale(.4);opacity:0;transition-delay:calc(var(--i) * 70ms + 250ms)}
/* הנדנוד על עטיפה פנימית, כדי שלא יתנגש ב-transform של הכניסה */
.aim-chips{list-style:none;margin:0;padding:0}
.aim-bob{display:block;animation:aim-bob var(--d,5s) ease-in-out infinite alternate;animation-delay:calc(var(--i) * -900ms)}
/* בלי הובר: התגיות אינן לחיצות, ותזוזה בהובר משדרת "לחיץ" */
.aim-pill{display:block;white-space:nowrap;background:var(--accent, #4a3aff);color:var(--accent-ink, #fff);font-weight:700;font-size:clamp(15px,1.35vw,19px);
  padding:12px 24px;border-radius:999px;box-shadow:0 12px 26px -14px color-mix(in srgb,var(--accent, #4a3aff) 80%,transparent)}
.aim-ptr{position:absolute;left:0;top:0;width:20px;height:18px;background:var(--accent, #4a3aff);clip-path:polygon(100% 50%,0 0,22% 50%,0 100%);
  transform:translate(var(--px,0),var(--py,0)) translate(-50%,-50%) rotate(var(--a,0deg))}
.aim.in .aim-disc{transform:scale(1);opacity:1}
.aim.in .aim-chip{transform:none;opacity:1}
@keyframes aim-bob{from{transform:translateY(-6px)}to{transform:translateY(6px)}}
@media (max-width:760px){
  .aim{height:auto;min-height:150vw}
