.hx{position:relative;height:min(80vh,760px);overflow:auto;overscroll-behavior:contain;margin-inline:var(--gutter, clamp(24px, 5vw, 96px));border:1px solid var(--line, #e4e4ee);border-radius:var(--r, 14px);background:var(--bg, #f7f7fa);isolation:isolate;scrollbar-width:thin}
.hx-slot{position:sticky;top:0;height:0;z-index:20}
.hx-hero{min-height:86%;display:flex;flex-direction:column;justify-content:flex-end;gap:16px;padding:112px var(--gutter, clamp(24px, 5vw, 96px)) 64px;
  background:linear-gradient(160deg,color-mix(in srgb,var(--accent, #4a3aff) 34%,var(--ink, #16182b)),var(--ink, #16182b) 72%);color:var(--bg, #f7f7fa)}
.hx-hero.is-light{background:linear-gradient(180deg,color-mix(in srgb,var(--accent, #4a3aff) 9%,var(--bg, #f7f7fa)),var(--bg, #f7f7fa));color:var(--ink, #16182b)}
.hx-hero small{font-size:14px;font-weight:600;opacity:.8}
.hx-hero h3{margin:0;max-width:16ch;font-size:clamp(34px,4.4vw,72px);line-height:1.02;font-weight:700}
.hx-hero p{margin:0;max-width:44ch;font-size:17px;line-height:1.5;opacity:.82}
.hx-sec{display:grid;grid-template-columns:1fr 1.2fr;gap:var(--gap, clamp(16px, 1.6vw, 36px));align-items:center;padding:96px var(--gutter, clamp(24px, 5vw, 96px));border-top:1px solid var(--line, #e4e4ee);scroll-margin-top:88px}
.hx-sec h4{margin:0 0 12px;font-size:clamp(24px,2.2vw,36px);line-height:1.1}
.hx-sec p{margin:0;max-width:40ch;font-size:16px;line-height:1.6;color:var(--muted, #6a6d85)}
.hx-blk{aspect-ratio:4/3;border-radius:var(--r, 14px);background:color-mix(in srgb,var(--ink, #16182b) 7%,var(--bg, #f7f7fa))}
@media (max-width:700px){.hx{height:78vh}.hx-sec{grid-template-columns:1fr;padding:64px var(--gutter, clamp(24px, 5vw, 96px))}.hx-hero{padding:112px var(--gutter, clamp(24px, 5vw, 96px)) 48px}}

/* ---- shared header atoms ---- */
/* the logo link is 44px tall like every other control in the row; the rows centre their items, so nothing moves */
.hlogo{display:inline-flex;align-items:center;justify-content:center;min-height:44px;font-weight:800;font-size:19px;white-space:nowrap;color:inherit;text-decoration:none}
.hlink{display:inline-flex;align-items:center;min-height:44px;padding:0 14px;border-radius:999px;font-size:15px;font-weight:500;color:inherit;text-decoration:none;opacity:.78;
  transition:opacity .15s cubic-bezier(.2,.6,.2,1),background .18s cubic-bezier(.2,.6,.2,1)}
.hbtn{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:0 20px;border-radius:12px;background:var(--accent, #4a3aff);color:var(--accent-ink, #fff);text-decoration:none;
  font-size:14px;font-weight:600;white-space:nowrap;transition:transform .18s cubic-bezier(.2,.6,.2,1),background .3s cubic-bezier(.2,.6,.2,1),color .3s cubic-bezier(.2,.6,.2,1),box-shadow .3s cubic-bezier(.2,.6,.2,1)}
@media (hover:hover) and (pointer:fine){.hlink:hover{opacity:1}.hbtn:hover{transform:translateY(-1px)}}
/* color:inherit: a button does not inherit colour by default, so currentColor lines were browser black on a dark hero (hd1, hd9) */
.hd .burger{display:none;color:inherit}
/* skip link: the first Tab stop on the page, out of sight until it has focus. On a real site it points at <main> */
.hskip{position:absolute;inset-inline-start:16px;top:-64px;z-index:30;display:inline-flex;align-items:center;min-height:44px;padding:0 16px;border-radius:10px;
  background:var(--ink, #16182b);color:var(--bg, #f7f7fa);font-size:15px;font-weight:600;text-decoration:none}
.hskip:focus{top:16px}
/* a hidden header takes its shadow with it: the shadow reaches past the header's own edge (up to 56px on the floating
   ones), and translateY(-100%) left it as a grey band on every light screen while scrolling down (Profix audit, 23.9.2026) */
.hd.is-hidden,.hd.is-hidden::before,.hd.is-hidden > *,.hd.is-hidden > *::before{box-shadow:none!important}
@media (prefers-reduced-motion:reduce){.hd,.hd *{transition-duration:.01ms!important;transition-delay:0s!important}}
.h4x{position:absolute;top:16px;inset-inline:16px;display:flex;align-items:center;justify-content:space-between;pointer-events:none;transition:transform .45s cubic-bezier(.2,.6,.2,1)}
.h4x>*{pointer-events:auto}
.h4x.is-hidden{transform:translateY(calc(-100% - 32px))}
.h4-chip{display:inline-flex;align-items:center;min-height:52px;padding:0 24px;border-radius:999px;background:var(--card, #fff);color:var(--ink, #16182b);text-decoration:none;font-weight:800;font-size:19px;
  box-shadow:0 8px 24px color-mix(in srgb,var(--ink, #16182b) 12%,transparent)}
.h4-menu{display:inline-flex;align-items:center;gap:12px;min-height:52px;padding:8px;padding-inline-start:20px;border:0;border-radius:999px;background:var(--ink, #16182b);color:var(--bg, #f7f7fa);
  font:inherit;font-size:15px;font-weight:600;cursor:pointer;box-shadow:0 8px 24px color-mix(in srgb,var(--ink, #16182b) 16%,transparent)}
.h4-menu i{position:relative;width:36px;height:36px;border-radius:50%;background:var(--bg, #f7f7fa)}
.h4-menu i::before,.h4-menu i::after{content:"";position:absolute;inset-inline:11px;height:2px;border-radius:2px;background:var(--ink, #16182b);transition:transform .3s cubic-bezier(.2,.6,.2,1)}
.h4-menu i::before{top:14px}
.h4-menu i::after{top:20px}
@media (hover:hover) and (pointer:fine){.h4-menu:hover i::before{transform:translateY(-1px)}.h4-menu:hover i::after{transform:translateY(1px)}}
.fs{position:fixed;inset:0;z-index:80;display:grid;grid-template-columns:1.4fr 1fr;align-items:end;gap:var(--gap, clamp(16px, 1.6vw, 36px));padding:112px var(--gutter, clamp(24px, 5vw, 96px)) 64px;background:var(--ink, #16182b);color:var(--bg, #f7f7fa);
  clip-path:circle(0px at var(--cx,90%) var(--cy,48px));visibility:hidden;transition:clip-path .7s cubic-bezier(.76,0,.24,1),visibility 0s linear .7s}
.fs.open{clip-path:circle(150vmax at var(--cx,90%) var(--cy,48px));visibility:visible;transition-delay:0s}
.fs-links{list-style:none;margin:0;padding:0}
.fs-links a{display:block;padding:4px 0;font-size:clamp(40px,6vw,96px);font-weight:700;line-height:1.05;color:var(--bg, #f7f7fa);text-decoration:none;opacity:0;transform:translateY(32px);
  transition:opacity .2s cubic-bezier(.2,.6,.2,1),transform .2s cubic-bezier(.2,.6,.2,1),color .2s cubic-bezier(.2,.6,.2,1)}
.fs.open .fs-links a{opacity:1;transform:none;transition-duration:.6s,.6s,.2s;transition-delay:calc(.25s + var(--i) * 60ms),calc(.25s + var(--i) * 60ms),0s}
.fs-side{display:grid;gap:8px;font-size:16px;line-height:1.6;color:color-mix(in srgb,var(--bg, #f7f7fa) 72%,transparent);opacity:0;transition:opacity .2s cubic-bezier(.2,.6,.2,1)}
.fs-side a{color:var(--bg, #f7f7fa);text-decoration:none}
.fs.open .fs-side{opacity:1;transition:opacity .5s cubic-bezier(.2,.6,.2,1) .55s}
.fs-close{position:absolute;top:16px;inset-inline-end:16px;display:inline-flex;align-items:center;gap:12px;min-height:52px;padding:8px;padding-inline-start:20px;border:0;border-radius:999px;
  background:var(--bg, #f7f7fa);color:var(--ink, #16182b);font:inherit;font-size:15px;font-weight:600;cursor:pointer}
.fs-close svg{width:36px;height:36px;padding:8px;border-radius:50%;background:var(--ink, #16182b);color:var(--bg, #f7f7fa)}
@media (hover:hover) and (pointer:fine){.fs-links a:hover{color:color-mix(in srgb,var(--accent, #4a3aff) 45%,var(--bg, #f7f7fa))}}
@media (max-width:700px){.fs{grid-template-columns:1fr;align-content:end;padding:112px var(--gutter, clamp(24px, 5vw, 96px)) 48px}}
@media (prefers-reduced-motion:reduce){.fs,.fs *{transition-duration:.01ms!important;transition-delay:0s!important}}

