/* ---- mobile drawer (shared by b65 and b66) ---- */
.md{position:fixed;inset:0;z-index:60;visibility:hidden;transition:visibility 0s linear .44s}
.md.open{visibility:visible;transition-delay:0s}
.md-scrim{position:absolute;inset:0;background:color-mix(in srgb,var(--ink, #16182b) 48%,transparent);opacity:0;transition:opacity .3s cubic-bezier(.2,.6,.2,1)}
.md.open .md-scrim{opacity:1}
.md-panel{position:absolute;inset-block:0;inset-inline-start:0;width:min(86vw,380px);background:var(--card, #fff);color:var(--ink, #16182b);
  display:flex;flex-direction:column;overflow:auto;padding:18px 24px 32px;box-shadow:0 0 48px color-mix(in srgb,var(--ink, #16182b) 18%,transparent);
  transform:translateX(100%);transition:transform .44s cubic-bezier(.76,0,.24,1)}
[dir="ltr"] .md-panel{transform:translateX(-100%)}
.md.open .md-panel{transform:none}
.md-top{display:flex;align-items:center;justify-content:space-between;padding-bottom:24px}
.md-close{width:44px;height:44px;border:0;border-radius:12px;background:color-mix(in srgb,var(--ink, #16182b) 6%,transparent);color:var(--ink, #16182b);display:grid;place-items:center;cursor:pointer;transition:background .18s cubic-bezier(.2,.6,.2,1),transform .44s cubic-bezier(.76,0,.24,1)}
.md.open .md-close{transform:rotate(90deg)}
.md-close svg{width:18px;height:18px}
.md-list{list-style:none;margin:0;padding:8px 0 0}
.md-item{opacity:0;transform:translateY(12px);
  transition:opacity .18s cubic-bezier(.2,.6,.2,1),transform .18s cubic-bezier(.2,.6,.2,1)}
.md.open .md-item{opacity:1;transform:none;transition-duration:.4s,.4s;transition-delay:calc(.14s + var(--i) * 45ms)}
.md-link,.md-acc{display:flex;align-items:center;justify-content:space-between;width:100%;min-height:56px;padding:12px 0;
  font:inherit;font-size:18px;font-weight:600;color:var(--ink, #16182b);text-decoration:none;background:none;border:0;cursor:pointer;text-align:start;transition:color .15s cubic-bezier(.2,.6,.2,1)}
/* chevron: physical borders on purpose, a logical inline-end flips it sideways in RTL */
.md-acc i{width:8px;height:8px;border-right:2px solid currentColor;border-bottom:2px solid currentColor;transform:rotate(45deg) translateY(-2px);transition:transform .3s cubic-bezier(.2,.6,.2,1)}
.md-acc[aria-expanded="true"]{color:var(--accent, #4a3aff)}
.md-acc[aria-expanded="true"] i{transform:rotate(225deg) translateY(-2px)}
.md-sub{display:grid;grid-template-rows:0fr;transition:grid-template-rows .32s cubic-bezier(.2,.6,.2,1)}
.md-sub.open{grid-template-rows:1fr}
.md-sub>div{overflow:hidden}
.md-sub h5{margin:8px 0 4px;font-size:13px;font-weight:600;color:var(--accent, #4a3aff)}
.md-sub a{display:block;padding:10px 16px;font-size:15px;color:var(--muted, #6a6d85);text-decoration:none;opacity:0;transform:translateX(8px);
  transition:opacity .2s cubic-bezier(.2,.6,.2,1),transform .2s cubic-bezier(.2,.6,.2,1),color .15s cubic-bezier(.2,.6,.2,1)}
[dir="ltr"] .md-sub a{transform:translateX(-8px)}
.md-sub.open a{opacity:1;transform:none;transition-delay:calc(var(--j) * 30ms)}
.md-sub>div>:last-child{margin-bottom:12px}
.md-cta{margin-top:24px;opacity:0;transform:translateY(12px);transition:opacity .18s,transform .18s}
.md.open .md-cta{opacity:1;transform:none;transition:opacity .4s cubic-bezier(.2,.6,.2,1) .42s,transform .4s cubic-bezier(.2,.6,.2,1) .42s}
.md-cta a{display:flex;justify-content:center;align-items:center;min-height:52px;border-radius:12px;background:var(--accent, #4a3aff);color:var(--accent-ink, #fff);font-weight:600;text-decoration:none}
@media (hover:hover) and (pointer:fine){.md-link:hover,.md-acc:hover,.md-sub a:hover{color:var(--accent, #4a3aff)}.md-close:hover,.burger:hover{background:color-mix(in srgb,var(--ink, #16182b) 12%,transparent)}}
.burger{width:44px;height:44px;border:0;transition:background .18s cubic-bezier(.2,.6,.2,1);border-radius:12px;background:color-mix(in srgb,var(--ink, #16182b) 6%,transparent);display:grid;place-content:center;gap:4px;cursor:pointer}
.burger i{display:block;width:18px;height:2px;background:var(--ink, #16182b);border-radius:2px;transition:transform .36s cubic-bezier(.76,0,.24,1),opacity .2s}
.burger[aria-expanded="true"] i:nth-child(1){transform:translateY(6px) rotate(45deg)}
.burger[aria-expanded="true"] i:nth-child(2){opacity:0}
.burger[aria-expanded="true"] i:nth-child(3){transform:translateY(-6px) rotate(-45deg)}
@media (prefers-reduced-motion:reduce){.md,.md *{transition-duration:.01ms!important;transition-delay:0s!important}}
.h5x{position:absolute;inset-inline:0;top:0;isolation:isolate;--ub:40px;transition:transform .4s cubic-bezier(.2,.6,.2,1)}
.h5x.is-scrolled{transform:translateY(calc(var(--ub) * -1))}
.h5x.is-hidden{transform:translateY(-100%)}
/* keyboard focus on a link in the folded bar brings the bar back, so the focus ring is never off screen */
.h5x.is-scrolled:has(.h5-util :focus-visible){transform:none}
.h5-util{display:flex;align-items:center;gap:24px;min-height:40px;padding:0 var(--gutter, clamp(24px, 5vw, 96px));background:var(--ink, #16182b);color:var(--bg, #f7f7fa);font-size:13px}
.h5-util a,.h5-util span{color:inherit;opacity:.85}
.h5-util a{position:relative;display:inline-flex;align-items:center;gap:8px;text-decoration:none}
/* hit areas on the phone without moving anything: the phone link's own box grows past 24px (padding, cancelled by a negative
   margin) and ::after takes the hit area to the bar's height; the language chips keep their 26px pill and get the same */
.h5-util>a{padding-block:4px;margin-block:-4px}
.h5-util>a::after{content:"";position:absolute;inset:-8px -4px}
/* a solid ring hugs the link; the default auto ring also wrapped the invisible hit area */
.h5-util a:focus-visible{outline:2px solid currentColor;outline-offset:2px;border-radius:6px}
.h5-lang a::after{content:"";position:absolute;inset:-7px -2px}
.h5-util svg{width:14px;height:14px}
.h5-lang{margin-inline-start:auto;display:flex;gap:4px}
