.t5-list input:checked + .t5-box{background:var(--accent, #4a3aff);box-shadow:none}
.t5-list input:checked + .t5-box svg{stroke-dashoffset:0}
.t5-list input:focus-visible + .t5-box{outline:2px solid var(--accent, #4a3aff);outline-offset:3px}
.t5-list b{display:block;font-size:16px;line-height:1.4;transition:color .2s cubic-bezier(.2,.6,.2,1)}
.t5-list small{display:block;font-size:14px;color:var(--muted, #6a6d85)}
.t5-list input:checked ~ span b{color:var(--muted, #6a6d85)}
.t5-ready{display:grid;grid-template-rows:0fr;transition:grid-template-rows .35s cubic-bezier(.2,.6,.2,1)}
