.nf-list a:hover{background:var(--card, #fff)}
/* walking the results with the arrows: the row in focus needs a ring, a white row on a near-white page is 1.06:1 */
.nf-list a:focus-visible{background:var(--card, #fff);outline:2px solid var(--accent, #4a3aff);outline-offset:-2px}
.nf-list a span{font-weight:600}
.nf-list a small{font-size:13px;color:var(--muted, #6a6d85);unicode-bidi:isolate}
.nf-list mark{background:color-mix(in srgb,var(--accent, #4a3aff) 18%,transparent);color:inherit;border-radius:3px}
.nf-empty{margin:0 0 32px;padding:16px;border-radius:12px;background:var(--card, #fff);color:var(--muted, #6a6d85)}
.nf-empty[hidden]{display:none}
.nf-out{display:flex;flex-wrap:wrap;gap:12px}

