function inView(el,f){
  var done=false,io=null;
  function go(){if(done)return;done=true;off();f();}
  function chk(){var r=el.getBoundingClientRect();if(r.top<innerHeight*.9&&r.bottom>0)go();}
  function off(){removeEventListener("scroll",chk);removeEventListener("resize",chk);if(io)io.disconnect();}
  // the observer also catches a layout change that brings the block on screen with no scroll event;
  // the scroll check stays for where the observer is late or missing
  if("IntersectionObserver" in window){io=new IntersectionObserver(function(es){if(es.some(function(x){return x.isIntersecting;}))go();},{rootMargin:"0px 0px -10% 0px"});io.observe(el);}
  addEventListener("scroll",chk,{passive:true});addEventListener("resize",chk);requestAnimationFrame(chk);setTimeout(chk,300);
}
function lev(a,b){var m=a.length,n=b.length,d=[],i,j;for(i=0;i<=m;i++)d[i]=[i];for(j=0;j<=n;j++)d[0][j]=j;
  for(i=1;i<=m;i++)for(j=1;j<=n;j++)d[i][j]=Math.min(d[i-1][j]+1,d[i][j-1]+1,d[i-1][j-1]+(a[i-1]===b[j-1]?0:1));return d;}
(function(){
  var root=document.getElementById("cv6");
  // the site map this page knows. On a real site it is generated from the routes at build time.
  var PAGES=[
    {t:"עיצוב מטבחים",u:"/services/kitchen",k:"מטבח מטבחים kitchen"},
    {t:"עיצוב סלון",u:"/services/living-room",k:"סלון living"},
    {t:"שיפוץ דירה מלא",u:"/services/renovation",k:"שיפוץ renovation דירה"},
    {t:"פרויקטים",u:"/projects",k:"עבודות תיק פורטפוליו projects"},
    {t:"מחירים",u:"/pricing",k:"מחיר עלות כמה pricing"},
    {t:"שאלות נפוצות",u:"/faq",k:"שאלות faq"},
    {t:"אודות הסטודיו",u:"/about",k:"אודות about מי"},
    {t:"צור קשר",u:"/contact",k:"קשר טלפון contact וואטסאפ"}];
  var path=root.querySelector("[data-path]"),shown=root.querySelector("[data-shown]"),guess=root.querySelector("[data-guess]"),h=root.querySelector("[data-h]");
  var q=root.querySelector("[data-q]"),list=root.querySelector("[data-list]"),empty=root.querySelector("[data-empty]");
  function clean(p){p=(p||"/").toLowerCase().split("?")[0].split("#")[0];return p.length>1&&p.charAt(p.length-1)==="/"?p.slice(0,-1):p;}
  // the corrected address, with the characters that were fixed marked (a backtrace over the edit matrix)
  function marked(from,to){
    var d=lev(from,to),i=from.length,j=to.length,out=[];
    while(j>0){
      if(i>0&&from[i-1]===to[j-1]&&d[i][j]===d[i-1][j-1]){out.unshift([to[j-1],0]);i--;j--;}
      else if(i>0&&d[i][j]===d[i-1][j-1]+1){out.unshift([to[j-1],1]);i--;j--;}
      else if(d[i][j]===d[i][j-1]+1){out.unshift([to[j-1],1]);j--;}
      else i--;
    }
    return out;
  }
  function run(){
    var p=clean(root.hasAttribute("data-demo")?path.value:location.pathname),best=null,score=1;
    shown.textContent=p;
    PAGES.forEach(function(g){
      var a=lev(p,g.u),full=a[p.length][g.u.length]/Math.max(p.length,g.u.length);
      var ls=p.split("/").pop(),lg=g.u.split("/").pop(),b=lev(ls,lg),last=b[ls.length][lg.length]/Math.max(ls.length,lg.length,1);
      var s=Math.min(full,last+.08);if(s<score){score=s;best=g;}
    });
    if(best&&score<=.45){
      guess.hidden=false;guess.href=best.u;guess.querySelector("[data-gt]").textContent=best.t;
      var gu=guess.querySelector("[data-gu]");gu.textContent="";
      marked(p,best.u).forEach(function(c){var n=c[1]?document.createElement("mark"):document.createTextNode(c[0]);if(c[1])n.textContent=c[0];gu.appendChild(n);});
      h.textContent="הכתובת הזו לא קיימת, אבל נראה שחיפשתם משהו קרוב";
    }else{guess.hidden=true;h.textContent="הכתובת הזו לא קיימת. בואו נמצא את מה שחיפשתם";}
  }
  // results are built with text nodes only: the query is user input and never becomes HTML
  function filter(){
    var v=q.value.trim().toLowerCase(),n=0;list.textContent="";
    PAGES.forEach(function(g){
      var hay=(g.t+" "+g.k).toLowerCase();if(v&&hay.indexOf(v)<0)return;if(!v&&n>=5)return;n++;
      var li=document.createElement("li"),a=document.createElement("a"),s=document.createElement("span"),sm=document.createElement("small"),at=g.t.toLowerCase().indexOf(v);
      a.href=g.u;sm.textContent=g.u;sm.dir="ltr";
      if(v&&at>-1){s.appendChild(document.createTextNode(g.t.slice(0,at)));var m=document.createElement("mark");m.textContent=g.t.slice(at,at+v.length);s.appendChild(m);s.appendChild(document.createTextNode(g.t.slice(at+v.length)));}
      else s.textContent=g.t;
      a.appendChild(s);a.appendChild(sm);li.appendChild(a);list.appendChild(li);
    });
    empty.hidden=n>0;
  }
  // arrow keys walk from the field through the results and back, Enter follows the link
  q.addEventListener("keydown",function(e){if(e.key==="ArrowDown"){var a=list.querySelector("a");if(a){e.preventDefault();a.focus();}}});
  list.addEventListener("keydown",function(e){
    var all=[].slice.call(list.querySelectorAll("a")),i=all.indexOf(document.activeElement);
    if(e.key==="ArrowDown"&&i<all.length-1){e.preventDefault();all[i+1].focus();}
    else if(e.key==="ArrowUp"){e.preventDefault();(i>0?all[i-1]:q).focus();}
    else if(e.key==="Escape"){q.focus();}
  });
  q.addEventListener("input",filter);path.addEventListener("input",run);
  run();filter();
  inView(root,function(){root.classList.add("is-in");});
})();

entries.css:
/* CV7 · 404 עם שביל חזרה ודיווח על הקישור */
.cx *{box-sizing:border-box}
.cx{--cx-err:color-mix(in srgb,#d23b22 72%,var(--ink, #16182b));font-size:16px;line-height:1.6;color:var(--ink, #16182b)}
.cx :where(a){color:inherit}
.cx :where(h2,h3){text-wrap:balance}
.cx :where(p,small,li){text-wrap:pretty}
.cx :focus-visible{outline:2px solid var(--accent, #4a3aff);outline-offset:3px;border-radius:8px}
.cx-btn{position:relative;display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:52px;padding:0 24px;border:0;border-radius:14px;
  background:var(--accent, #4a3aff);color:var(--accent-ink, #fff);font:inherit;font-size:16px;font-weight:600;text-decoration:none;cursor:pointer;white-space:nowrap;
  transition:transform .18s cubic-bezier(.2,.6,.2,1),background .2s cubic-bezier(.2,.6,.2,1),box-shadow .2s cubic-bezier(.2,.6,.2,1)}
.cx-btn svg{width:20px;height:20px;flex:none}
.cx-btn:active{transform:scale(.97)}
.cx-btn.is-ghost{background:transparent;color:var(--ink, #16182b);box-shadow:inset 0 0 0 1.5px color-mix(in srgb,var(--ink, #16182b) 22%,transparent)}
@media (hover:hover) and (pointer:fine){.cx-btn:hover{transform:translateY(-1px)}.cx-btn.is-ghost:hover{box-shadow:inset 0 0 0 1.5px var(--ink, #16182b)}
  .cx a:hover .ic-arr,.cx-btn:hover .ic-arr{transform:translateX(-4px)}}
.ic-arr{transition:transform .2s cubic-bezier(.2,.6,.2,1)}
[dir="ltr"] .ic-arr{rotate:180deg}
.cx-rv{opacity:0;transform:translateY(16px);transition:opacity .5s cubic-bezier(.2,.6,.2,1),transform .5s cubic-bezier(.2,.6,.2,1);transition-delay:calc(var(--i,0) * 80ms)}
.is-in .cx-rv{opacity:1;transform:none}
/* a time or a phone number never breaks between rows ("050-000" on one, "0000" on the next, at 500) */
.cx-t{unicode-bidi:isolate;font-variant-numeric:tabular-nums;white-space:nowrap}
/* the demo switch: lets the reviewer see every state. Not part of the component you copy. */
.cx-demo{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:0 0 24px;padding:6px;border-radius:14px;background:color-mix(in srgb,var(--ink, #16182b) 5%,transparent);font-size:13px;width:max-content;max-width:100%}
.cx-demo > span{padding:0 10px;font-weight:600;color:var(--muted, #6a6d85)}
.cx-demo button{min-height:36px;padding:0 14px;border:0;border-radius:10px;background:none;font:inherit;font-weight:600;color:var(--ink, #16182b);cursor:pointer;transition:background .18s cubic-bezier(.2,.6,.2,1),color .18s cubic-bezier(.2,.6,.2,1)}
.cx-demo button[aria-pressed="true"]{background:var(--card, #fff);box-shadow:0 1px 3px color-mix(in srgb,var(--ink, #16182b) 14%,transparent)}
.cx-demo input{min-height:36px;padding:0 12px;border:0;border-radius:10px;background:var(--card, #fff);font:inherit;font-size:14px;color:var(--ink, #16182b);width:220px}
@media (prefers-reduced-motion:reduce){.cx *,.cx *::before,.cx *::after{transition-duration:.01ms!important;transition-delay:0s!important;animation-duration:.01ms!important;animation-iteration-count:1!important}.cx-rv{opacity:1;transform:none}}
.cxw{margin-inline:var(--gutter, clamp(24px, 5vw, 96px));border-radius:var(--r, 14px);background:var(--bg, #f7f7fa);box-shadow:0 0 0 1px var(--line, #e4e4ee);overflow:hidden;isolation:isolate}
.cxw-in{max-width:640px;margin-inline:auto;padding:72px 24px 88px}
@media (max-width:700px){.cxw-in{padding:48px 20px 64px}}
.t7-h{margin:0 0 8px;font-size:clamp(28px,3.8vw,40px);line-height:1.12;font-weight:700}
.t7-sub{margin:0 0 24px;color:var(--muted, #6a6d85)}
.t7-trail{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:0 0 48px;padding:0;list-style:none}
.t7-trail li{display:flex;align-items:center;gap:6px}
/* the separators are decoration: an empty alt text keeps screen readers from saying "angle bracket";
   the plain value comes first, for browsers that do not know the alt syntax */
.t7-trail li + li::before{content:"‹";content:"‹" / "";color:var(--muted, #6a6d85);font-size:18px}
[dir="ltr"] .t7-trail li + li::before{content:"›";content:"›" / ""}
.t7-c{position:relative;display:inline-flex;align-items:center;min-height:40px;padding:0 14px;border-radius:999px;background:var(--card, #fff);font-size:15px;font-weight:600;text-decoration:none;
  transition:background .18s cubic-bezier(.2,.6,.2,1),color .18s cubic-bezier(.2,.6,.2,1)}
a.t7-c{box-shadow:inset 0 0 0 1.5px color-mix(in srgb,var(--ink, #16182b) 10%,transparent)}
@media (hover:hover) and (pointer:fine){a.t7-c:hover{background:var(--ink, #16182b);color:var(--bg, #f7f7fa)}}
.t7-bad{color:var(--cx-err);background:color-mix(in srgb,var(--cx-err) 8%,transparent);unicode-bidi:isolate}
/* the strike is drawn in the reading direction of the address (left to right), after the trail has settled */
.t7-bad::after{content:"";position:absolute;left:12px;right:12px;top:50%;height:2px;border-radius:2px;background:currentColor;transform:scaleX(0);transform-origin:left;transition:transform .45s cubic-bezier(.2,.6,.2,1) .5s}
.is-in .t7-bad::after{transform:scaleX(1)}
.t7-fix::before{content:"←";content:"←" / "";margin-inline-end:6px;opacity:.8}
[dir="ltr"] .t7-fix::before{content:"→";content:"→" / ""}
.t7-fix{background:var(--accent, #4a3aff);color:var(--accent-ink, #fff);opacity:0;transform:translateX(8px);transition:opacity .3s cubic-bezier(.2,.6,.2,1) .95s,transform .3s cubic-bezier(.2,.6,.2,1) .95s,background .18s cubic-bezier(.2,.6,.2,1)}
.is-in .t7-fix{opacity:1;transform:none}
.t7-skip{color:var(--muted, #6a6d85);background:transparent;box-shadow:inset 0 0 0 1.5px color-mix(in srgb,var(--ink, #16182b) 10%,transparent);unicode-bidi:isolate}
.t7-top h3{margin:0 0 16px;font-size:15px;font-weight:600;color:var(--muted, #6a6d85)}
.t7-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:0 0 40px}
.t7-grid a{display:grid;grid-template-columns:minmax(0,1fr);gap:12px;padding:12px 12px 16px;border-radius:18px;background:var(--card, #fff);text-decoration:none;transition:transform .2s cubic-bezier(.2,.6,.2,1),box-shadow .2s cubic-bezier(.2,.6,.2,1)}
.t7-grid i{display:block;min-width:0;aspect-ratio:2/1;border-radius:12px;background:color-mix(in srgb,var(--accent, #4a3aff) calc(var(--k) * 8%),var(--bg, #f7f7fa));transition:transform .4s cubic-bezier(.2,.6,.2,1)}
.t7-grid b{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:0 4px;font-size:16px}
.t7-grid b svg{width:18px;height:18px}
@media (hover:hover) and (pointer:fine){.t7-grid a:hover{transform:translateY(-2px);box-shadow:0 14px 32px color-mix(in srgb,var(--ink, #16182b) 10%,transparent)}}
.t7-rep{display:flex;flex-wrap:wrap;align-items:center;gap:12px 16px;padding:20px;border-radius:18px;background:color-mix(in srgb,var(--ink, #16182b) 4%,transparent)}
.t7-rep[hidden]{display:none}
.t7-rep p{flex:1 1 240px;margin:0;font-size:15px;color:var(--muted, #6a6d85)}
.t7-rep .cx-btn{min-height:48px;font-size:15px;overflow:hidden}
.t7-rep .cx-btn span{display:inline-flex;align-items:center;gap:8px;transition:transform .25s cubic-bezier(.2,.6,.2,1),opacity .25s cubic-bezier(.2,.6,.2,1)}
.t7-rep .cx-btn span + span{position:absolute;inset:0;justify-content:center;opacity:0;transform:translateY(100%)}
.t7-rep .cx-btn span svg{width:18px;height:18px}
.t7-rep .is-sent span:first-child{opacity:0;transform:translateY(-100%)}
.t7-rep .is-sent span + span{opacity:1;transform:none}
.t7-rep .is-sent{background:var(--ink, #16182b);color:var(--bg, #f7f7fa);pointer-events:none}
/* read by screen readers only: the live report line, and "not found:" before the broken part of the trail.
   Its own rule, so the component does not depend on a page-level .sr-only */
.t7-said{position:absolute;width:1px;height:1px;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
@media (pointer:coarse),(max-width:760px){.t7-c{min-height:44px}}

