function lev(a,b){var m=a.length,n=b.length,d=[],i,j;for(i=0;i<=m;i++)d[i]=[i];for(j=0;j<=n;j++)d[0][j]=j;
  for(i=1;i<=m;i++)for(j=1;j<=n;j++)d[i][j]=Math.min(d[i-1][j]+1,d[i][j-1]+1,d[i-1][j-1]+(a[i-1]===b[j-1]?0:1));return d;}
(function(){
  var root=document.getElementById("cv9"),form=root.querySelector("form"),sum=root.querySelector("[data-summary]"),sug=root.querySelector("[data-suggest]"),touched={};
  var DOMAINS=["gmail.com","walla.co.il","walla.com","hotmail.com","outlook.com","yahoo.com","icloud.com","012.net.il","bezeqint.net","netvision.net.il"];
  function digits(v){return v.replace(/[^0-9]/g,"");}
  function normPhone(v){var d=digits(v);if(d.indexOf("972")===0)d="0"+d.slice(3);return d;}
  // mobile (05x) and VoIP (07x) are ten digits; landlines (02, 03, 04, 08, 09) are nine. A nine-digit 05 is a mobile missing a digit, not a landline.
  function fmtPhone(d){if(/^0[57][0-9]{8}$/.test(d))return d.slice(0,3)+"-"+d.slice(3,6)+"-"+d.slice(6);if(/^0[2-489][0-9]{7}$/.test(d))return d.slice(0,2)+"-"+d.slice(2,5)+"-"+d.slice(5);return null;}
  // the messages say what is missing, in numbers when there is a number to say
  var RULES={
    name:function(v){v=v.trim();if(!v)return "איך לפנות אליכם? חסר שם";if(v.length<2)return "שם של אות אחת? כתבו לפחות שתיים";return "";},
    phone:function(v){var d=normPhone(v),miss;if(!d)return "חסר מספר טלפון";
      if(/^0[57]/.test(d)){if(d.length<10){miss=10-d.length;return (miss===1?"חסרה ספרה אחת":"חסרות "+miss+" ספרות")+" (מספר נייד הוא 10 ספרות)";}
        if(d.length>10)return (d.length-10===1?"יש ספרה אחת מיותרת":"יש "+(d.length-10)+" ספרות מיותרות")+" (מספר נייד הוא 10 ספרות)";}
      return fmtPhone(d)?"":"המספר לא נראה כמו טלפון ישראלי";},
    email:function(v){v=v.trim();if(!v)return "חסרה כתובת מייל";if(v.indexOf("@")<0)return "בכתובת חסר @";if(!/^[^@ ]+@[^@ ]+[.][^@ ]{2,}$/.test(v))return "הכתובת לא שלמה, למשל name@gmail.com";return "";}
  };
  var inputs=[].slice.call(form.querySelectorAll("[data-v]"));
  function check(inp,show){
    var k=inp.getAttribute("data-v"),f=inp.closest(".g9-f"),m=RULES[k](inp.value);
    if(show||touched[k]){f.classList.toggle("is-bad",!!m);f.classList.toggle("is-ok",!m&&inp.value.trim()!=="");inp.setAttribute("aria-invalid",m?"true":"false");if(m)f.querySelector(".g9-err span").textContent=m;}
    return m;
  }
  function suggest(inp){
    var v=inp.value.trim(),at=v.lastIndexOf("@");if(at<1){sug.classList.remove("is-open");return;}
    var dom=v.slice(at+1).toLowerCase(),best=null,bd=9;if(DOMAINS.indexOf(dom)>-1){sug.classList.remove("is-open");return;}
    DOMAINS.forEach(function(d){var x=lev(dom,d)[dom.length][d.length];if(x<bd){bd=x;best=d;}});
    // a likely typo is not "correct": the tick waits until the suggestion is taken or the address is retyped
    if(best&&bd<=2){var fixed=v.slice(0,at+1)+best;sug.querySelector("[data-fixed]").textContent=fixed;sug.fixed=fixed;sug.classList.add("is-open");inp.closest(".g9-f").classList.remove("is-ok");}else sug.classList.remove("is-open");
  }
  sug.querySelector("button").addEventListener("click",function(){var inp=form.querySelector("[data-v=email]");inp.value=sug.fixed;sug.classList.remove("is-open");check(inp,true);inp.focus();});
  inputs.forEach(function(inp){
    var k=inp.getAttribute("data-v");
    // on leaving the field: tidy the phone into its format, then judge. An empty untouched field is left alone.
    inp.addEventListener("blur",function(){
      if(inp.value.trim()===""&&!touched[k])return;
      if(k==="phone"){var f=fmtPhone(normPhone(inp.value));if(f)inp.value=f;}
      touched[k]=true;check(inp,true);if(k==="email")suggest(inp);
    });
    // after the first mistake it re-checks while typing, so the error leaves the moment it is fixed and never arrives mid-word
    inp.addEventListener("input",function(){if(touched[k])check(inp,true);if(k==="email")sug.classList.remove("is-open");});
  });
  // the summary is live: a line leaves as its field is fixed, and the box closes when nothing is left
  function summary(focus){
    var bad=inputs.filter(function(inp){return RULES[inp.getAttribute("data-v")](inp.value);}),ul=sum.querySelector("ul");ul.textContent="";
    bad.forEach(function(inp){var li=document.createElement("li"),a=document.createElement("a");a.href="#"+inp.id;
      a.textContent=inp.closest(".g9-f").querySelector("label").textContent+": "+RULES[inp.getAttribute("data-v")](inp.value);
      a.addEventListener("click",function(ev){ev.preventDefault();inp.focus();});li.appendChild(a);ul.appendChild(li);});
    sum.querySelector("[data-count]").textContent=bad.length===1?"שדה אחד צריך תיקון":bad.length+" שדות צריכים תיקון";
    sum.classList.toggle("is-open",bad.length>0);
    if(focus&&bad.length){sum.focus({preventScroll:true});sum.scrollIntoView({block:"nearest",behavior:"smooth"});}
    return bad.length;
  }
  form.addEventListener("input",function(){if(sum.classList.contains("is-open"))summary(false);});
  form.addEventListener("focusout",function(){setTimeout(function(){if(sum.classList.contains("is-open"))summary(false);},0);});
  form.addEventListener("submit",function(e){
    e.preventDefault();
    inputs.forEach(function(inp){var k=inp.getAttribute("data-v");touched[k]=true;if(k==="phone"){var f=fmtPhone(normPhone(inp.value));if(f)inp.value=f;}check(inp,true);});
    suggest(form.querySelector("[data-v=email]"));
    if(summary(true))return;
    // the form (and the button that had focus) disappears: focus moves to the confirmation, which is also read out
    root.classList.add("is-sent");var done=root.querySelector(".g9-done");done.textContent="נשלח. נחזור אליכם עוד היום.";done.focus({preventScroll:true});
  });
})();

entries.css:
/* מחלקות עזר של המאגר שהרכיב הזה משתמש בהן */
.stage{padding:var(--sec, clamp(120px, 12vw, 260px)) var(--gutter, clamp(24px, 5vw, 96px));position:relative}
.stage.tight{padding-block:clamp(48px,5vw,90px)}
.stage.full{padding-inline:0}
.ph{display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700;border-radius:var(--r, 14px)}
.ph-a{background:linear-gradient(160deg,#3b5bdb,#748ffc)}
.ph-b{background:linear-gradient(160deg,#5f3dc4,#9775fa)}
.ph-c{background:linear-gradient(160deg,#0b7285,#3bc9db)}
.ph-d{background:linear-gradient(160deg,#2b8a3e,#69db7c)}
.ph-e{background:linear-gradient(160deg,#e8590c,#ffa94d)}

/* B67 · גלולה תחתונה שנפתחת לתפריט */
.bn{display:grid;place-items:center}
.bn-phone{position:relative;width:min(390px,100%);height:min(78vh,760px);border-radius:40px;overflow:hidden;background:var(--bg, #f7f7fa);isolation:isolate;
  box-shadow:0 0 0 10px var(--ink, #16182b),0 32px 64px color-mix(in srgb,var(--ink, #16182b) 24%,transparent)}
.bn-scr{height:100%;overflow:auto;overscroll-behavior:contain;scrollbar-width:none}
.bn-scr::-webkit-scrollbar{display:none}
.bn-sec{padding:32px 24px 40px}
.bn-sec:focus{outline:none} /* יעד פוקוס אחרי בחירת קישור, לא פקד */
.bn-sec:first-child{padding-top:56px}
.bn-sec:last-child{padding-bottom:112px}
.bn-sec h3{margin:0 0 8px;font-size:26px;line-height:1.15}
.bn-sec p{margin:0 0 16px;color:var(--muted, #6a6d85);font-size:16px;line-height:1.6}
.bn-img{height:180px;margin-bottom:20px;border-radius:18px}
/* כהות מתחת לכרטיס הפתוח: לחיצה עליה סוגרת */
.bn-scrim{position:absolute;inset:0;z-index:4;background:color-mix(in srgb,var(--ink, #16182b) 38%,transparent);opacity:0;pointer-events:none;transition:opacity .35s cubic-bezier(.2,.6,.2,1)}
.bn.open .bn-scrim{opacity:1;pointer-events:auto}
/* משטח אחד: clip-path חותך ממנו את הגלולה בתחתית. הצל על ההורה, כי clip-path חותך גם צל */
.bn-nav{--pw:204px;--ph:56px;position:absolute;inset-inline:16px;bottom:16px;z-index:5;
  filter:drop-shadow(0 14px 22px color-mix(in srgb,var(--ink, #16182b) 30%,transparent));transition:transform .45s cubic-bezier(.2,.6,.2,1);pointer-events:none}
/* הקופסה של התפריט בגובה הכרטיס הפתוח גם כשהוא סגור, ושקופה היא עדיין תופסת לחיצות וגלגלת מעל חצי המסך התחתון.
   בסגור רק הגלולה לחיצה, בפתוח כל הכרטיס */
.bn-bar-in,.bn.open .bn-sheet{pointer-events:auto}
.bn.hide .bn-nav{transform:translateY(calc(var(--ph) + 24px))}
.bn-sheet{background:var(--ink, #16182b);color:var(--bg, #f7f7fa);border-radius:28px;
  clip-path:inset(calc(100% - var(--ph)) calc(50% - var(--pw) / 2) 0 round 28px);transition:clip-path .5s cubic-bezier(.76,0,.24,1)}
.bn.open .bn-sheet{clip-path:inset(0 0 0 round 28px)}
.bn-links{list-style:none;margin:0;padding:24px 16px 8px;display:grid;gap:4px}
.bn-links a,.bn-cta{opacity:0;transform:translateY(16px);transition:opacity .15s,transform .15s,background-color .2s}
.bn.open .bn-links a,.bn.open .bn-cta{opacity:1;transform:none;
  transition:opacity .35s calc(var(--i) * 60ms + 180ms),transform .45s calc(var(--i) * 60ms + 180ms) cubic-bezier(.2,.6,.2,1),background-color .2s}
.bn-links a{display:flex;align-items:center;justify-content:space-between;padding:12px;border-radius:14px;font-size:22px;font-weight:600;color:inherit}
@media (hover:hover) and (pointer:fine){.bn-links a:hover{background:color-mix(in srgb,var(--bg, #f7f7fa) 10%,transparent)}}
.bn-links a:focus-visible,.bn-cta:focus-visible,.bn-btn:focus-visible{outline:2px solid var(--accent, #4a3aff);outline-offset:2px}
.bn-links a[aria-current]::after{content:"";width:8px;height:8px;border-radius:50%;background:var(--accent, #4a3aff)}
.bn-cta{display:flex;justify-content:center;margin:8px 16px 12px;padding:14px 20px;border-radius:999px;background:var(--accent, #4a3aff);color:var(--accent-ink, #fff);font-weight:700}
.bn-bar{height:var(--ph);display:flex;justify-content:center}
.bn-bar-in{width:var(--pw);display:flex;align-items:center;justify-content:space-between;padding-inline:20px 6px}
.bn-where{display:flex;align-items:center;gap:8px;min-width:0;height:24px;overflow:hidden;font-size:15px;font-weight:600}
.bn-dot{flex:none;width:8px;height:8px;border-radius:50%;background:var(--accent, #4a3aff)}
.bn-label{display:block;white-space:nowrap}
.bn-label.roll{animation:bn-roll .4s cubic-bezier(.2,.6,.2,1)}
@keyframes bn-roll{from{transform:translateY(100%);opacity:0}to{transform:none;opacity:1}}
.bn-btn{position:relative;flex:none;width:44px;height:44px;border:0;border-radius:50%;background:color-mix(in srgb,var(--bg, #f7f7fa) 14%,transparent);display:grid;place-items:center;cursor:pointer;transition:background-color .2s}
.bn-btn i{position:absolute;width:18px;height:2px;border-radius:2px;background:var(--bg, #f7f7fa);transition:transform .35s cubic-bezier(.76,0,.24,1)}
.bn-btn i:first-child{transform:translateY(-4px)}
.bn-btn i:last-child{transform:translateY(4px)}
.bn.open .bn-btn i:first-child{transform:rotate(45deg)}
.bn.open .bn-btn i:last-child{transform:rotate(-45deg)}
@media (prefers-reduced-motion: reduce){.bn-sheet,.bn-nav,.bn-scrim,.bn-links a,.bn-cta,.bn-btn i{transition-duration:.01ms;transition-delay:0s}.bn-label.roll{animation:none}}

