(function(){
  const root=document.querySelector(".bn"),scr=root.querySelector(".bn-scr"),card=root.querySelector(".bn-card");
  const btn=root.querySelector(".bn-btn"),scrim=root.querySelector(".bn-scrim"),label=root.querySelector(".bn-label");
  const links=[...root.querySelectorAll(".bn-links a")],cta=root.querySelector(".bn-cta"),secs=[...root.querySelectorAll(".bn-sec")];
  const reduced=matchMedia("(prefers-reduced-motion: reduce)").matches;
  const isOpen=()=>root.classList.contains("open");
  card.inert=true;
  // to: לאן הפוקוס עובר בסגירה. בלי יעד, ורק אם הפוקוס היה בתוך הכרטיס, הוא חוזר לכפתור:
  // inert על הכרטיס מפיל את הפוקוס ל-body, ומשתמש מקלדת היה מתחיל שוב מראש העמוד
  function set(open,to){
    const had=card.contains(document.activeElement);
    root.classList.toggle("open",open);root.classList.remove("hide");
    btn.setAttribute("aria-expanded",String(open));
    btn.setAttribute("aria-label",open?"סגירת התפריט":"פתיחת התפריט");
    card.inert=!open;scr.inert=open; // בזמן שהתפריט פתוח, הדף מתחת לא נגיש ולא לחיץ
    if(open)(links.find(a=>a.hasAttribute("aria-current"))||links[0]).focus({preventScroll:true});
    else if(to||had)(to||btn).focus({preventScroll:true});
  }
  btn.addEventListener("click",()=>set(!isOpen()));
  scrim.addEventListener("click",()=>set(false,btn));
  root.addEventListener("keydown",e=>{if(e.key==="Escape"&&isOpen())set(false,btn);});
  links.concat(cta).forEach(a=>a.addEventListener("click",e=>{
    const t=root.querySelector(a.getAttribute("href"));if(!t)return;
    // הפוקוס עובר לסקשן שנבחר, כך שה-Tab הבא ממשיך משם
    e.preventDefault();t.tabIndex=-1;set(false,t);
    scr.scrollTo({top:t.offsetTop,behavior:reduced?"auto":"smooth"});
  }));
  // שם הסקשן הנוכחי בגלולה, וסימון הקישור שלו בכרטיס
  let cur=-1;
  function mark(i){
    if(i<0||i===cur)return;cur=i;
    label.textContent=secs[i].dataset.label;
    if(!reduced){label.classList.remove("roll");void label.offsetWidth;label.classList.add("roll");}
    links.forEach((a,k)=>{if(k===i)a.setAttribute("aria-current","location");else a.removeAttribute("aria-current");});
  }
  const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)mark(secs.indexOf(e.target));}),{root:scr,rootMargin:"-40% 0px -55% 0px"});
  secs.forEach(s=>io.observe(s));
  mark(0);
  // יורדת מהדרך בגלילה למטה, חוזרת בגלילה למעלה ובסוף העמוד (שם נמצא הצעד הבא)
  let last=0;
  scr.addEventListener("scroll",()=>{
    const y=scr.scrollTop,d=y-last;last=y;
    if(isOpen())return;
    const end=scr.scrollHeight-y-scr.clientHeight<40;
    if(d>6&&y>80&&!end)root.classList.add("hide");
    else if(d<-6||end)root.classList.remove("hide");
  },{passive:true});
})();

entries.css:
/* מחלקות עזר של המאגר שהרכיב הזה משתמש בהן */
.ph{display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700;border-radius:var(--r, 14px)}
.ph-a{background:linear-gradient(160deg,#3b5bdb,#748ffc)}
.ph-b{background:linear-gradient(160deg,#5f3dc4,#9775fa)}
.ph-c{background:linear-gradient(160deg,#0b7285,#3bc9db)}
.ph-d{background:linear-gradient(160deg,#2b8a3e,#69db7c)}

/* G150 · אקורדיון שנפתח בגלילה */
.sa{padding:var(--sec, clamp(120px, 12vw, 260px)) var(--gutter, clamp(24px, 5vw, 96px))}
.sa-head{max-width:52ch;margin:0 0 clamp(32px,4vw,64px)}
.sa-head h2{margin:0 0 12px;font-size:var(--fs-h2, clamp(28px, 1.9vw + 0.5rem, 52px))}
.sa-head p{margin:0;color:var(--muted, #6a6d85)}
.sa-pin{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.05fr);gap:clamp(32px,5vw,96px);align-items:center;min-height:min(80vh,700px)}
.sa-list{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.sa-item{padding-block:16px}
.sa-q{display:flex;align-items:baseline;gap:16px;width:100%;padding:10px 0;margin-block:-10px;border:0;background:none;font:inherit;color:inherit;text-align:start;cursor:pointer}
.sa-q:focus-visible{outline:2px solid var(--accent, #4a3aff);outline-offset:6px;border-radius:6px}
.sa-n{flex:none;width:24px;font-size:15px;font-weight:600;color:var(--muted, #6a6d85);font-variant-numeric:tabular-nums;transition:color .35s}
.sa-t{font-size:clamp(22px,2vw,34px);font-weight:600;line-height:1.15;color:color-mix(in srgb,var(--ink, #16182b) 40%,var(--bg, #f7f7fa));transition:color .4s cubic-bezier(.2,.6,.2,1)}
.sa-item.on .sa-t{color:var(--ink, #16182b)}
.sa-item.on .sa-n{color:var(--ink, #16182b)}
/* הפס הוא המידע (כמה נשאר מהשלב), לא קישוט: הוא קיים רק מתחת לשלב הפתוח. מתחת לכל שלב הוא היה ארבעה קווים ברצף */
.sa-bar{display:block;height:2px;margin-top:12px;margin-inline-start:40px;border-radius:2px;overflow:hidden;background:transparent;transition:background-color .4s}
.sa-item.on .sa-bar{background:color-mix(in srgb,var(--ink, #16182b) 10%,transparent)}
.sa-bar i{display:block;height:100%;background:var(--accent, #4a3aff);transform:scaleX(0);transform-origin:right;transition:transform .6s cubic-bezier(.2,.6,.2,1),opacity .3s}
.sa-item.on .sa-bar i{transform:scaleX(1)}
.sa-item:not(.on) .sa-bar i{opacity:0}
.sa-p{display:grid;grid-template-rows:0fr;transition:grid-template-rows .5s cubic-bezier(.2,.6,.2,1)}
.sa-item.on .sa-p{grid-template-rows:1fr}
.sa-p>div{overflow:hidden}
.sa-p p{margin:0;padding-top:12px;padding-inline-start:40px;max-width:46ch;color:var(--muted, #6a6d85);font-size:17px;line-height:1.6;opacity:0;transform:translateY(8px);transition:opacity .2s,transform .2s}
